def solve(inp, out_n):
    n=len(inp); c=inp.index(2)
    G=[[0]*out_n for _ in range(out_n)]
    for r in range(out_n):
        for i in range(out_n):
            if (i-r)%4 == c%4 and abs(i-c)<=r:
                G[r][i]=1
    for r in range(out_n):
        for i in (c-r, c+r):
            if 0<=i<out_n:
                G[r][i]=2
    return G
